function cloneJson(value){return value===undefined?undefined:JSON.parse(JSON.stringify(value));}
class HttpParams {
 constructor(input={}){this.pairs=[];if(typeof input==='string'){for(const part of input.replace(/^\?/,'').split('&').filter(Boolean)){const [key,...rest]=part.split('=');this.pairs.push([decodeURIComponent(key.replaceAll('+',' ')),decodeURIComponent(rest.join('=').replaceAll('+',' '))]);}}else for(const[k,v]of Object.entries(input))this.pairs.push([k,String(v)]);}
 set(k,v){this.pairs=this.pairs.filter(p=>p[0]!==k);this.pairs.push([String(k),String(v)]);}
 toString(){return this.pairs.map(([k,v])=>encodeURIComponent(k)+'='+encodeURIComponent(v)).join('&');}
}
class HttpUrl {
 constructor(input){
  const value=String(input);if(/[\u0000-\u0020\u007f\\]/.test(value))throw new Error('AMBIGUOUS_URL');
  const match=value.match(/^(https?):\/\/([A-Za-z0-9.-]+)(?::([0-9]{1,5}))?((?:\/[^?#]*)?)(\?[^#]*)?(#.*)?$/i);
  if(!match||match[2].startsWith('.')||match[2].endsWith('.')||match[2].includes('..')||match[2].split('.').some(p=>!p||p.startsWith('-')||p.endsWith('-'))||(match[3]&&(+match[3]<1||+match[3]>65535)))throw new Error('INVALID_HTTP_URL');
  this.protocol=match[1].toLowerCase()+':';this.hostname=match[2].toLowerCase();this.port=match[3]??'';if((this.protocol==='https:'&&this.port==='443')||(this.protocol==='http:'&&this.port==='80'))this.port='';
  this.origin=this.protocol+'//'+this.hostname+(this.port?':'+this.port:'');this.pathname=match[4]||'/';this.username='';this.password='';this.searchParams=new HttpParams(match[5]??'');this.hash=match[6]??'';
 }
 get href(){const q=this.searchParams.toString();return this.origin+this.pathname+(q?'?'+q:'')+this.hash;}
 toString(){return this.href;}
}

const URL=HttpUrl,URLSearchParams=HttpParams,structuredClone=cloneJson;

return [{json:{...$input.first().json,retry_setup_execution_id:$execution.id,scope:'Combined original and identity-corrected isolated test; unchanged $2/28-call ceiling; no prospect sends'}}];
